-- CCNA Dumps: complete T1-T3 / E1-E3 tip (Thomas, 2026-11-14)
-- Anki-NF-1491 (T1) and Anki-NF-1494 (E1) tips now list all six rates.

UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Leased Lines (WAN)</div><p>A T1 leased line provides 1.544 Mbps. It is made of 24 DS0 channels of 64 kbps each, and it is the standard North American digital leased line.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>T1</strong>: T1 provides 1.544 Mbps of bandwidth, which is the rate of 24 DS0 channels at 64 kbps each.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>T3</strong>: T3 provides 44.736 Mbps, far faster than 1.544 Mbps.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>E1</strong>: E1 provides 2.048 Mbps and is the European standard, not 1.544 Mbps.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>T2</strong>: T2 provides 6.312 Mbps, not 1.544 Mbps.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><ul><li>T1 = 1.544 Mbps.</li><li>T2 = 6.312 Mbps.</li><li>T3 = 44.736 Mbps.</li><li>E1 = 2.048 Mbps.</li><li>E2 = 8.448 Mbps.</li><li>E3 = 34.368 Mbps.</li><li>Learn the T and E pairs together.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 53 Flashcards - WAN Architectures)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1491';
UPDATE questions SET explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: Leased Lines (WAN)</div><p>An E1 leased line provides 2.048 Mbps. It is the European standard, made of 32 channels of 64 kbps, and it is the counterpart of the North American T1.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answer (Option C) is Correct:</h4><ul><li><span class=\"opt-tag correct\">Option C</span> <strong>E1</strong>: E1 provides 2.048 Mbps of bandwidth.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>E2</strong>: E2 provides 8.448 Mbps, not 2.048 Mbps.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>T2</strong>: T2 provides 6.312 Mbps, not 2.048 Mbps.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>T1</strong>: T1 provides 1.544 Mbps and is the North American standard, not the European one.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><ul><li>T1 = 1.544 Mbps.</li><li>T2 = 6.312 Mbps.</li><li>T3 = 44.736 Mbps.</li><li>E1 = 2.048 Mbps.</li><li>E2 = 8.448 Mbps.</li><li>E3 = 34.368 Mbps.</li><li>Learn the T and E pairs together.</li></ul></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 53 Flashcards - WAN Architectures)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1494';
